custom_fields.content:
[[[
  const dbEntity = states['sensor.champion_multas_activas'];
  if (!dbEntity || ['unknown', 'unavailable'].includes(dbEntity.state)
      || dbEntity.attributes?.error || !Array.isArray(dbEntity.attributes?.items)) {
    return `<div style="padding:8px;color:var(--error-color);">
      ⚠️ Base de datos no disponible. Revisa el sensor y los registros de Home Assistant.
    </div>`;
  }

  const e = states['sensor.champion_multas_activas'];
  const items = e?.attributes?.items || [];

  if (!items.length) {
    return `
      <div style="text-align:center;opacity:.72;padding:8px 0;">
        ✅ No hay multas activas
      </div>
    `;
  }

  const playerName = p =>
    p === 'player1' ? 'player1' :
    p === 'player2' ? 'player2' : p;

  return `
    <div style="
      width:100%;
      display:grid;
      grid-template-columns:70px 1fr 90px 2fr;
      gap:7px 12px;
      align-items:center;
      font-size:12px;
    ">
      <div style="font-weight:800;opacity:.65;">ID</div>
      <div style="font-weight:800;opacity:.65;">NIÑO</div>
      <div style="font-weight:800;opacity:.65;">MULTA</div>
      <div style="font-weight:800;opacity:.65;">MOTIVO</div>

      ${items.map(x => `
        <div style="font-weight:900;">#${x.penalty_id}</div>
        <div>${playerName(x.player_key)}</div>
        <div style="font-weight:900;">−${x.amount} XP</div>
        <div style="opacity:.82;">${x.reason || 'Sin motivo'}</div>
      `).join('')}
    </div>
  `;
]]]

