custom_fields.content:
[[[
  const dbEntity = states['sensor.champion_historico'];
  if (!dbEntity || ['unknown', 'unavailable'].includes(dbEntity.state)
      || dbEntity.attributes?.error || !Array.isArray(dbEntity.attributes?.weeks) || !Array.isArray(dbEntity.attributes?.years)) {
    return `<div style="padding:8px;color:var(--error-color);">
      ⚠️ Base de datos no disponible. Revisa el sensor y los registros de Home Assistant.
    </div>`;
  }

  const e = states['sensor.champion_historico'];
  const weeks = e?.attributes?.weeks || [];
  const years = e?.attributes?.years || [];
  const error = e?.attributes?.error;

  if (error) {
    return `
      <div style="padding:8px;color:var(--error-color);">
        ⚠️ Base de datos no disponible.
      </div>
    `;
  }

  const realWeeks = weeks.filter(x => Number(x.year) !== 2099);
  const testWeeks = weeks.filter(x => Number(x.year) === 2099);

  return `
    <div style="
      display:grid;
      grid-template-columns:repeat(3,1fr);
      gap:12px;
      width:100%;
    ">
      <div style="text-align:center;">
        <div style="font-size:11px;opacity:.65;font-weight:800;">
          SEMANAS REALES
        </div>
        <div style="font-size:26px;font-weight:900;color:var(--lf-accent);">
          ${realWeeks.length}
        </div>
      </div>
      <div style="text-align:center;">
        <div style="font-size:11px;opacity:.65;font-weight:800;">
          RESÚMENES ANUALES
        </div>
        <div style="font-size:26px;font-weight:900;color:var(--lf-accent);">
          ${years.filter(x => Number(x.year) !== 2099).length}
        </div>
      </div>
      <div style="text-align:center;">
        <div style="font-size:11px;opacity:.65;font-weight:800;">
          DATOS DE PRUEBA
        </div>
        <div style="font-size:26px;font-weight:900;color:var(--lf-accent);">
          ${testWeeks.length}
        </div>
      </div>
    </div>
  `;
]]]

