  const dbEntity = states['sensor.champion_historico'];
  if (!dbEntity || ['unknown', 'unavailable'].includes(dbEntity.state)
      || dbEntity.attributes?.error || !Array.isArray(dbEntity.attributes?.weeks) || !Array.isArray(dbEntity.attributes?.years)) {
    return `<div style="padding:8px;color:var(--error-color);">
      ⚠️ Base de datos no disponible. Revisa el sensor y los registros de Home Assistant.
    </div>`;
  }

  const years = states['sensor.champion_historico']?.attributes?.years || [];
  const rows = years.filter(x =>
    x.player_key === 'player1' && Number(x.year) !== 2099
  );

  if (!rows.length) {
    return `
      <div style="text-align:center;opacity:.68;padding:12px;">
        Aún no hay años reales con semanas cerradas.
      </div>
    `;
  }

  const y = rows[0];
  return `
    <div style="width:100%;">
      <div style="font-size:18px;font-weight:900;margin-bottom:12px;">
        ${y.year}
      </div>
      <div style="
        display:grid;
        grid-template-columns:repeat(3,1fr);
        gap:12px;
        text-align:center;
      ">
        <div><b>${y.weeks_played}</b><br><span style="opacity:.65;font-size:11px;">SEMANAS</span></div>
        <div><b>${y.tasks_completed}/${y.tasks_due}</b><br><span style="opacity:.65;font-size:11px;">MISIONES</span></div>
        <div><b>${Number(y.completion_pct).toFixed(1)}%</b><br><span style="opacity:.65;font-size:11px;">COMPLETADO</span></div>
        <div><b>${y.effective_xp} XP</b><br><span style="opacity:.65;font-size:11px;">XP EFECTIVO</span></div>
        <div><b>${y.perfect_days}</b><br><span style="opacity:.65;font-size:11px;">DÍAS PERFECTOS</span></div>
        <div><b>${y.weekly_goals_achieved}</b><br><span style="opacity:.65;font-size:11px;">OBJETIVOS</span></div>
      </div>
    </div>
  `;
]]]

