custom_fields.content:
[[[
  const dbEntity = states['sensor.champion_historico'];
  if (!dbEntity || ['unknown', 'unavailable'].includes(dbEntity.state)
      || dbEntity.attributes?.error || !Array.isArray(dbEntity.attributes?.weeks) || !Array.isArray(dbEntity.attributes?.years)) {
    return `<div style="padding:8px;color:var(--error-color);">
      ⚠️ Base de datos no disponible. Revisa el sensor y los registros de Home Assistant.
    </div>`;
  }

  const weeks = states['sensor.champion_historico']?.attributes?.weeks || [];

  if (!weeks.length) {
    return `
      <div style="text-align:center;opacity:.68;padding:12px;">
        No hay semanas cerradas.
      </div>
    `;
  }

  const player = p =>
    p === 'player1' ? 'player1' :
    p === 'player2' ? 'player2' : p;

  const rows = weeks.map(x => {
    const test = Number(x.year) === 2099;
    const goal = Number(x.weekly_goal_achieved) === 1 ? '✅' : '—';
    const penalty = Number(x.penalty_xp) > 0
      ? `−${x.penalty_xp}`
      : '0';

    return `
      <div style="
        display:grid;
        grid-template-columns:1.2fr 1fr 1.35fr 1fr .9fr .9fr 1fr .7fr;
        gap:8px;
        align-items:center;
        padding:9px 0;
        border-top:1px solid var(--lf-panel-divider);
        ${test ? 'opacity:.68;' : ''}
      ">
        <div style="font-weight:800;">${player(x.player_key)}</div>
        <div>${x.year}-W${String(x.iso_week).padStart(2,'0')}</div>
        <div>${x.tasks_completed}/${x.tasks_due} · ${Number(x.completion_pct).toFixed(1)}%</div>
        <div>${x.task_xp} XP</div>
        <div>+${x.bonus_xp}</div>
        <div>${penalty}</div>
        <div style="font-weight:900;">${x.effective_xp}</div>
        <div>${goal}${test ? ' 🧪' : ''}</div>
      </div>
    `;
  }).join('');

  return `
    <div style="width:100%;overflow-x:auto;">
      <div style="min-width:0;">
        <div style="
          display:grid;
          grid-template-columns:1.2fr 1fr 1.35fr 1fr .9fr .9fr 1fr .7fr;
          gap:8px;
          font-size:10px;
          font-weight:900;
          opacity:.62;
          padding-bottom:7px;
        ">
          <div>NIÑO</div>
          <div>SEMANA</div>
          <div>MISIONES</div>
          <div>XP TAREAS</div>
          <div>BONUS</div>
          <div>MULTAS</div>
          <div>XP FINAL</div>
          <div>OBJ.</div>
        </div>
        ${rows}
      </div>
    </div>
  `;
]]]

