state.value:
[[[
  const day = new Date().getDay();
  const index = (day + 6) % 7;
  const bit = 1 << index;

  return (Number(entity.state) & bit) !== 0;
]]]

tap_action.service:
[[[
  const day = new Date().getDay();
  const index = (day + 6) % 7;
  const bit = 1 << index;

  return (Number(entity.state) & bit) !== 0
    ? 'script.champ_player1_desmarcar_mision'
    : 'script.champ_player1_marcar_mision';
]]]

service_data.fecha:
[[[
  const d = new Date();

  return `${d.getFullYear()}-${String(
    d.getMonth() + 1
  ).padStart(2,'0')}-${String(
    d.getDate()
  ).padStart(2,'0')}`;
]]]

custom_fields.content:
[[[
  const path =
    states['sensor.champ_season_path']?.state ||
    '/local/level_up_family/season_01';

  const season =
    Number(
      states['input_number.champ_season_number']?.state || 1
    );

  const names = {
    1: 'ZERO POINT',
    2: 'THE CONVERGENCE',
    3: 'CHROME STORM',
    4: 'NEON BLOOM',
    5: 'SOLAR DRIFT',
    6: 'FRACTURE POINT',
    7: 'THE DEEP',
    8: 'STATIC',
    9: 'HOLLOW EARTH',
    10: 'AFTERGLOW',
    11: 'OVERRIDE',
    12: 'THE FINALE'
  };

  const remainingRaw = states['sensor.champ_season_days_remaining']?.state;
  const remaining = Number(remainingRaw);
  const seasonStatus = states['sensor.champ_season_status']?.state;
  const validRemaining = typeof remainingRaw === 'string'
    && remainingRaw.trim() !== '' && Number.isFinite(remaining)
    && remaining >= 0 && remaining <= 28;
  const seasonCountdown = seasonStatus === 'finalizada'
    ? 'TEMPORADA FINALIZADA'
    : seasonStatus === 'pendiente'
      ? 'PENDIENTE DE INICIO'
      : seasonStatus === 'activa' && validRemaining
        ? `${remaining} ${remaining === 1 ? 'DÍA RESTANTE' : 'DÍAS RESTANTES'}`
        : 'TEMPORADA SIN CONFIGURAR';

  return `
    <div style="
      width:100%;
      height:100%;
      display:flex;
      flex-direction:column;
    ">

      <div style="
        flex:1 1 auto;
        min-height:0;
        background-image:url('${path}/banner.png');
        background-size:cover;
        background-position:center;
        background-repeat:no-repeat;
      ">
      </div>

      <div style="
        flex:0 0 auto;
        display:flex;
        justify-content:center;
        align-items:center;
        gap:16px;
        padding:12px 18px;
        color:white;
      ">

        <img
          src="${path}/icono_temporada.png"
          style="
            width:52px;
            height:52px;
            object-fit:contain;
          "
        >

        <div style="text-align:left;">

          <div style="
            font-size:16px;
            font-weight:900;
            letter-spacing:1px;
          ">
            TEMPORADA ${season} · ${names[season] || ''}
          </div>

          <div style="
            margin-top:3px;
            font-size:13px;
            font-weight:900;
            letter-spacing:1.5px;
            color:#65ddff;
          ">
            ${seasonCountdown}
          </div>

        </div>

      </div>

    </div>
  `;
]]]

card.border:
[[[
  const theme =
    states['sensor.champ_theme']?.attributes || {};

  const border =
    theme.border ||
    'rgba(90, 190, 255, 0.40)';

  return `1px solid ${border}`;
]]]

custom_fields.content:
[[[
  // ========================================================
  // FUENTE CENTRAL DEL TEMA
  // ========================================================

  const themeEntity =
    states['sensor.champ_theme'];

  const theme =
    themeEntity?.attributes || {};


  // ========================================================
  // SENSOR DE OBJETIVO SEMANAL
  //
  // Toda la lógica de objetivo está fuera del dashboard.
  // ========================================================

  const goalEntity =
    states[
      'binary_sensor.player1_objetivo_semanal_conseguido'
    ];

  const goal =
    goalEntity?.attributes || {};

  const achieved =
    goalEntity?.state === 'on';


  // ========================================================
  // DATOS DE PROGRESO
  // ========================================================

  const completed =
    Number(
      goal.misiones_completadas || 0
    );

  const due =
    Number(
      goal.misiones_previstas ?? 0
    );

  const pct =
    Number(
      goal.porcentaje_actual || 0
    );

  const target =
    Number(
      goal.objetivo_pct || 75
    );


  // ========================================================
  // NIVEL
  // ========================================================

  const totalXP =
    Number(
      states[
        'input_number.champ_player1_points_total'
      ]?.state || 0
    );

  const level =
    Math.floor(totalXP / 500) + 1;


  // ========================================================
  // ASSETS
  // ========================================================

  const path =
    theme.season_path ||
    states['sensor.champ_season_path']?.state ||
    '/local/level_up_family/season_01';


  // ========================================================
  // TEMA DE TEMPORADA
  // ========================================================

  const primary =
    theme.primary || '#7a28ff';

  const secondary =
    theme.secondary || '#d66cff';

  const highlight =
    theme.highlight || '#ff9cff';

  const accent =
    theme.accent || '#65ddff';

  const glow =
    theme.glow ||
    'rgba(169, 62, 255, 0.85)';

  const track =
    theme.track || '#07132f';

  const borderStrong =
    theme.border_strong ||
    'rgba(93, 125, 255, 0.72)';


  // ========================================================
  // TEMA UNIVERSAL DE OBJETIVO CONSEGUIDO
  // ========================================================

  const successPrimary =
    theme.success_primary || '#d99000';

  const successSecondary =
    theme.success_secondary || '#ffbd18';

  const successHighlight =
    theme.success_highlight || '#fff0a0';

  const successAccent =
    theme.success_accent || '#ffd83d';

  const successBorder =
    theme.success_border ||
    'rgba(255, 200, 35, 0.92)';

  const successGlow =
    theme.success_glow ||
    'rgba(255, 183, 0, 0.95)';


  // ========================================================
  // COLORES ACTIVOS DE LA BARRA
  //
  // Objetivo NO conseguido:
  //   tema de la temporada.
  //
  // Objetivo conseguido:
  //   dorado universal.
  // ========================================================

  const barPrimary =
    achieved
      ? successPrimary
      : primary;

  const barSecondary =
    achieved
      ? successSecondary
      : secondary;

  const barHighlight =
    achieved
      ? successHighlight
      : highlight;

  const barGlow =
    achieved
      ? successGlow
      : glow;

  const barBorder =
    achieved
      ? successBorder
      : borderStrong;

  const percentageColor =
    achieved
      ? successAccent
      : accent;


  // ========================================================
  // POSICIÓN DE LA MARCA DE OBJETIVO
  //
  // Ya NO existe ningún 75 fijo en el dashboard.
  // ========================================================

  const targetPosition =
    Math.max(
      0,
      Math.min(100, target)
    );


  // ========================================================
  // HTML
  // ========================================================

  return `
    <div style="
      box-sizing:border-box;

      width:100%;
      height:100%;

      display:flex;
      flex-direction:column;

      justify-content:center;

      padding:14px 20px 16px;

      color:white;
    ">


      <!-- =================================================
           player1 + NIVEL
           ================================================= -->

      <div style="
        display:flex;
        align-items:flex-start;
        justify-content:space-between;

        width:100%;
      ">


        <!-- NOMBRE -->

        <div style="
          text-align:left;

