              text-shadow .35s ease;
          ">
            ${pct}%
          </div>

          <div style="
            margin-top:3px;

            font-size:10px;

            color:${
              achieved
                ? successHighlight
                : 'white'
            };

            opacity:${
              achieved
                ? '1'
                : '.72'
            };

            font-weight:${
              achieved
                ? '900'
                : '400'
            };

            transition:
              color .35s ease;
          ">
            OBJETIVO ${target}%
          </div>

        </div>

      </div>


      <!-- =================================================
           BARRA DE PROGRESO
           ================================================= -->

      <div style="
        position:relative;

        box-sizing:border-box;

        width:100%;
        height:14px;

        margin-top:10px;

        border-radius:10px;

        background:${track};

        border:
          1px solid
          ${barBorder};

        box-shadow:
          inset 0 0 7px
          rgba(0,0,0,.75),

          ${
            achieved
              ? `
                0 0 8px ${successGlow},
                0 0 16px ${successGlow}
              `
              : '0 0 0 transparent'
          };

        overflow:visible;

        transition:
          border .35s ease,
          box-shadow .35s ease;
      ">


        <!-- =================================================
             RELLENO
             ================================================= -->

        <div style="
          position:absolute;

          left:1px;
          top:1px;
          bottom:1px;

          width:
            ${
              pct > 0
                ? `calc(${pct}% - 2px)`
                : '0'
            };

          max-width:
            calc(100% - 2px);

          border-radius:8px;

          background:
            linear-gradient(
              90deg,

              ${barPrimary} 0%,

              ${barSecondary} 68%,

              ${barHighlight} 100%
            );

          box-shadow:

            0 0
            ${achieved ? '9px' : '6px'}
            ${barGlow},

            0 0
            ${achieved ? '20px' : '13px'}
            ${barGlow},

            ${
              achieved
                ? `0 0 28px ${barGlow}`
                : '0 0 0 transparent'
            };

          transition:
            width .45s ease,
            background .35s ease,
            box-shadow .35s ease;
        ">


          <!-- EXTREMO LUMINOSO -->

          ${
            pct > 0
              ? `
                <div style="
                  position:absolute;

                  right:-1px;
                  top:0;

                  width:
                    ${achieved ? '11px' : '9px'};

                  height:100%;

                  border-radius:50%;

                  background:
                    ${barHighlight};

                  box-shadow:

                    0 0 6px
                    ${barHighlight},

                    0 0
                    ${achieved ? '18px' : '12px'}
                    ${barGlow};
                ">
                </div>
              `
              : ''
          }

        </div>


        <!-- =================================================
             MARCA DINÁMICA DEL OBJETIVO
             ================================================= -->

        <div style="
          position:absolute;

          left:${targetPosition}%;

          top:-2px;
          bottom:-2px;

          width:2px;

          transform:
            translateX(-1px);

          background:
