[[[
  const path =
    states['sensor.champ_season_path']?.state ||
    '/local/level_up_family/season_01';

  const season =
    Number(
      states['input_number.champ_season_number']?.state || 1
    );

  const names = {
    1: 'ZERO POINT',
    2: 'THE CONVERGENCE',
    3: 'CHROME STORM',
    4: 'NEON BLOOM',
    5: 'SOLAR DRIFT',
    6: 'FRACTURE POINT',
    7: 'THE DEEP',
    8: 'STATIC',
    9: 'HOLLOW EARTH',
    10: 'AFTERGLOW',
    11: 'OVERRIDE',
    12: 'THE FINALE'
  };

  const remainingRaw = states['sensor.champ_season_days_remaining']?.state;
  const remaining = Number(remainingRaw);
  const seasonStatus = states['sensor.champ_season_status']?.state;
  const validRemaining = typeof remainingRaw === 'string'
    && remainingRaw.trim() !== '' && Number.isFinite(remaining)
    && remaining >= 0 && remaining <= 28;
  const seasonCountdown = seasonStatus === 'finalizada'
    ? 'TEMPORADA FINALIZADA'
    : seasonStatus === 'pendiente'
      ? 'PENDIENTE DE INICIO'
      : seasonStatus === 'activa' && validRemaining
        ? `${remaining} ${remaining === 1 ? 'DÍA RESTANTE' : 'DÍAS RESTANTES'}`
        : 'TEMPORADA SIN CONFIGURAR';

  return `
    <div style="
      width:100%;
      height:100%;
      display:flex;
      flex-direction:column;
    ">

