custom_fields.content:
[[[
  // ========================================================
  // FUENTE CENTRAL DEL TEMA
  // ========================================================

  const themeEntity =
    states['sensor.champ_theme'];

  const theme =
    themeEntity?.attributes || {};


  // ========================================================
  // SENSOR DE OBJETIVO SEMANAL
  //
  // Toda la lógica de objetivo está fuera del dashboard.
  // ========================================================

  const goalEntity =
    states[
      'binary_sensor.player2_objetivo_semanal_conseguido'
    ];

  const goal =
    goalEntity?.attributes || {};

  const achieved =
    goalEntity?.state === 'on';


  // ========================================================
  // DATOS DE PROGRESO
  // ========================================================

  const completed =
    Number(
      goal.misiones_completadas || 0
    );

  const due =
    Number(
      goal.misiones_previstas ?? 0
    );

  const pct =
    Number(
      goal.porcentaje_actual || 0
    );

  const target =
    Number(
      goal.objetivo_pct || 75
    );


  // ========================================================
  // NIVEL
  // ========================================================

  const totalXP =
    Number(
      states[
        'input_number.champ_player2_points_total'
      ]?.state || 0
    );

  const level =
    Math.floor(totalXP / 500) + 1;


  // ========================================================
  // ASSETS
  // ========================================================

  const path =
    theme.season_path ||
    states['sensor.champ_season_path']?.state ||
    '/local/level_up_family/season_01';


  // ========================================================
  // TEMA DE TEMPORADA
  // ========================================================

  const primary =
    theme.primary || '#7a28ff';

  const secondary =
    theme.secondary || '#d66cff';

  const highlight =
    theme.highlight || '#ff9cff';

  const accent =
    theme.accent || '#65ddff';

  const glow =
    theme.glow ||
    'rgba(169, 62, 255, 0.85)';

  const track =
    theme.track || '#07132f';

  const borderStrong =
    theme.border_strong ||
    'rgba(93, 125, 255, 0.72)';


  // ========================================================
  // TEMA UNIVERSAL DE OBJETIVO CONSEGUIDO
  // ========================================================

  const successPrimary =
    theme.success_primary || '#d99000';

  const successSecondary =
    theme.success_secondary || '#ffbd18';

  const successHighlight =
    theme.success_highlight || '#fff0a0';

  const successAccent =
    theme.success_accent || '#ffd83d';

  const successBorder =
    theme.success_border ||
    'rgba(255, 200, 35, 0.92)';

  const successGlow =
    theme.success_glow ||
    'rgba(255, 183, 0, 0.95)';


  // ========================================================
  // COLORES ACTIVOS DE LA BARRA
  //
  // Objetivo NO conseguido:
  //   tema de la temporada.
  //
  // Objetivo conseguido:
  //   dorado universal.
  // ========================================================

  const barPrimary =
    achieved
      ? successPrimary
      : primary;

  const barSecondary =
    achieved
      ? successSecondary
      : secondary;

  const barHighlight =
    achieved
      ? successHighlight
      : highlight;

  const barGlow =
    achieved
      ? successGlow
      : glow;

  const barBorder =
    achieved
      ? successBorder
      : borderStrong;

  const percentageColor =
    achieved
      ? successAccent
      : accent;


  // ========================================================
  // POSICIÓN DE LA MARCA DE OBJETIVO
  //
  // Ya NO existe ningún 75 fijo en el dashboard.
  // ========================================================

  const targetPosition =
    Math.max(
      0,
      Math.min(100, target)
    );


  // ========================================================
  // HTML
  // ========================================================

  return `
    <div style="
      box-sizing:border-box;

      width:100%;
      height:100%;

      display:flex;
      flex-direction:column;

      justify-content:center;

      padding:14px 20px 16px;

      color:white;
    ">


      <!-- =================================================
           player2 + NIVEL
           ================================================= -->

      <div style="
        display:flex;
        align-items:flex-start;
        justify-content:space-between;

        width:100%;
      ">


        <!-- NOMBRE -->

        <div style="
          text-align:left;

          font-size:20px;
          line-height:22px;

          font-weight:900;

          letter-spacing:.3px;
        ">
          player2
        </div>


        <!-- NIVEL -->

        <div style="
          display:flex;
          align-items:center;

          gap:7px;

          margin-top:-2px;
        ">

          <img
            src="${path}/icono_nivel.png"

            style="
              width:30px;
              height:30px;

              object-fit:contain;

              filter:
                drop-shadow(
                  0 0 6px
                  ${glow}
                );
            "
          >

          <div style="
            display:flex;
            flex-direction:column;

            align-items:flex-start;

            line-height:1;
          ">

            <div style="
              font-size:10px;
              font-weight:800;

              opacity:.72;

              letter-spacing:.7px;
            ">
              NIVEL
            </div>

            <div style="
              margin-top:2px;

              font-size:18px;
              font-weight:900;

              color:${accent};
            ">
              ${level}
            </div>

          </div>

        </div>

      </div>


      <!-- =================================================
           PROGRESO
           ================================================= -->

      <div style="
        display:flex;

        justify-content:space-between;
        align-items:flex-end;

        margin-top:10px;
      ">


        <!-- IZQUIERDA -->

        <div style="
          text-align:left;
        ">

          <div style="
            font-size:16px;
            line-height:18px;

            font-weight:900;
          ">
            PROGRESO SEMANAL
          </div>

          <div style="
            margin-top:3px;

            font-size:11px;

            opacity:.72;
          ">
            ${completed} / ${due} MISIONES
          </div>

        </div>


        <!-- DERECHA -->

        <div style="
          text-align:right;
        ">

          <div style="
            font-size:28px;
            line-height:28px;

            font-weight:900;

            color:${percentageColor};

            text-shadow:
              0 0
              ${achieved ? '15px' : '10px'}
              ${barGlow};

            transition:
              color .35s ease,
              text-shadow .35s ease;
          ">
            ${pct}%
          </div>

          <div style="
            margin-top:3px;

            font-size:10px;

            color:${
              achieved
                ? successHighlight
                : 'white'
            };

            opacity:${
              achieved
                ? '1'
                : '.72'
            };

            font-weight:${
              achieved
                ? '900'
                : '400'
            };

            transition:
              color .35s ease;
          ">
            OBJETIVO ${target}%
          </div>

        </div>

      </div>


      <!-- =================================================
           BARRA DE PROGRESO
           ================================================= -->

      <div style="
        position:relative;

        box-sizing:border-box;

        width:100%;
        height:14px;

        margin-top:10px;

        border-radius:10px;

        background:${track};

        border:
          1px solid
          ${barBorder};

        box-shadow:
          inset 0 0 7px
          rgba(0,0,0,.75),

          ${
            achieved
              ? `
                0 0 8px ${successGlow},
                0 0 16px ${successGlow}
              `
              : '0 0 0 transparent'
          };

        overflow:visible;

        transition:
          border .35s ease,
          box-shadow .35s ease;
      ">


        <!-- =================================================
             RELLENO
             ================================================= -->

        <div style="
          position:absolute;

          left:1px;
          top:1px;
          bottom:1px;

          width:
            ${
              pct > 0
                ? `calc(${pct}% - 2px)`
                : '0'
            };

          max-width:
            calc(100% - 2px);

          border-radius:8px;

          background:
            linear-gradient(
              90deg,

              ${barPrimary} 0%,

              ${barSecondary} 68%,

              ${barHighlight} 100%
            );

          box-shadow:

            0 0
            ${achieved ? '9px' : '6px'}
            ${barGlow},

            0 0
            ${achieved ? '20px' : '13px'}
            ${barGlow},

            ${
              achieved
                ? `0 0 28px ${barGlow}`
                : '0 0 0 transparent'
            };

          transition:
            width .45s ease,
            background .35s ease,
            box-shadow .35s ease;
        ">


          <!-- EXTREMO LUMINOSO -->

          ${
            pct > 0
              ? `
                <div style="
                  position:absolute;

                  right:-1px;
                  top:0;

                  width:
                    ${achieved ? '11px' : '9px'};

                  height:100%;

                  border-radius:50%;

                  background:
                    ${barHighlight};

                  box-shadow:

                    0 0 6px
                    ${barHighlight},

                    0 0
                    ${achieved ? '18px' : '12px'}
                    ${barGlow};
                ">
                </div>
              `
              : ''
          }

        </div>


        <!-- =================================================
             MARCA DINÁMICA DEL OBJETIVO
             ================================================= -->

        <div style="
          position:absolute;

          left:${targetPosition}%;

          top:-2px;
          bottom:-2px;

          width:2px;

          transform:
            translateX(-1px);

          background:
            rgba(255,255,255,.92);

          border-radius:2px;

          box-shadow:
            0 0 5px
            rgba(255,255,255,.9);

          z-index:5;

          transition:
            left .35s ease;
        ">
        </div>


      </div>

    </div>
  `;
]]]

