[[[
  const t = states['sensor.champ_theme']?.attributes || {};
  const streak = Number(
    states['input_number.champ_player2_streak_weeks']?.state || 0
  );

  return streak >= 2
    ? `linear-gradient(
        135deg,
        ${t.success_primary || '#d99000'},
        ${t.success_secondary || '#ffbd18'}
      )`
    : (t.card_background || 'rgba(3,12,35,.92)');
]]]

card.border:
[[[
  const t = states['sensor.champ_theme']?.attributes || {};
  const streak = Number(
    states['input_number.champ_player2_streak_weeks']?.state || 0
  );

  return `1px solid ${
    streak >= 2
      ? (t.success_border || 'rgba(255,200,35,.92)')
      : (t.border || 'rgba(90,190,255,.40)')
  }`;
]]]

card.box-shadow:
[[[
  const t = states['sensor.champ_theme']?.attributes || {};
  const streak = Number(
    states['input_number.champ_player2_streak_weeks']?.state || 0
  );

  return streak >= 2
    ? `0 0 18px ${t.success_glow || 'rgba(255,183,0,.95)'}`
    : '0 7px 22px rgba(0,0,0,.32)';
]]]

custom_fields.content:
[[[
  const t = states['sensor.champ_theme']?.attributes || {};

  const path =
    t.season_path ||
    '/local/level_up_family/season_01';

  const streak = Math.round(
    Number(
      states['input_number.champ_player2_streak_weeks']?.state || 0
    )
  );

  const multiplier = Number(
    states['input_number.champ_weekly_streak_multiplier']?.state || 1
  );

  const active = streak >= 2;

  const secondary = active
    ? 'rgba(0,0,0,.68)'
    : (t.text_secondary || 'rgba(255,255,255,.72)');

  const mainColor =
    active ? '#07132f' : '#ffffff';

  const multiplierText =
    multiplier
      .toFixed(2)
      .replace(/0+$/, '')
      .replace(/\.$/, '');

  return `
    <div style="
      box-sizing:border-box;
      width:100%;
      height:100%;
      display:flex;
      align-items:center;
      justify-content:center;
      gap:9px;
      padding:8px;
    ">

      <img
        src="${path}/icono_bonus.png"
        style="
          width:43px;
          height:43px;
          object-fit:contain;
          flex:0 0 auto;
        "
      >

      <div style="text-align:left;">

        <div style="
          color:${secondary};
          font-size:9px;
          font-weight:900;
          letter-spacing:.4px;
          white-space:nowrap;
        ">
          BONUS RACHA
        </div>

        <div style="
          margin-top:3px;
          color:${mainColor};
          font-size:${active ? '20px' : '13px'};
          line-height:22px;
          font-weight:900;
          white-space:nowrap;
        ">
          ${
            active
              ? `×${multiplierText}`
              : 'PENDIENTE'
          }
        </div>

      </div>
    </div>
  `;
]]]

variables.dia_perfecto:
