{% set ns = namespace(due=0, done=0) %}
{% set b = [1,2,4,8,16,32,64][indice_dia | int] %}
{% for task in tasks if not task.once %}
  {% if task.days | bitwise_and(b) %}
    {% set ns.due = ns.due + 1 %}
    {% if states(task.entity) | int(0) | bitwise_and(b) %}{% set ns.done = ns.done + 1 %}{% endif %}
  {% endif %}
{% endfor %}
{{ 1 if ns.due > 0 and ns.done == ns.due else 0 }}

variables.calculo_dias_semana:
{% set tasks = state_attr('sensor.champ_task_catalog', 'tasks') | default([], true) | selectattr('player', 'eq', 'player2') | list %}
{% set ns = namespace(total=0) %}
{% set limit = 7 %}
{% for i in range(limit | int) %}
  {% set b = [1,2,4,8,16,32,64][i] %}
  {% set day = namespace(due=0, done=0) %}
  {% for task in tasks if not task.once %}
    {% if task.days | bitwise_and(b) %}
